using Microsoft.ML;

namespace TicketClassifier.Services;

/// <summary>
/// Provides the ordered score labels extracted from the trained model schema.
/// </summary>
public class ModelMetadataService
{
    public string[] ScoreLabels { get; }

    public ModelMetadataService(IWebHostEnvironment env)
    {
        var modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        var mlContext = new MLContext();
        var model = mlContext.Model.Load(modelPath, out _);

        // Get the output schema and extract slot names from the Score column
        var outputSchema = model.GetOutputSchema(SchemaDefinition.Create(typeof(Models.TicketData)));
        var scoreColumn = outputSchema["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);
        ScoreLabels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

